entity tb_bbq_priority_encoder_core is end;architecture sim of tb_bbq_priority_encoder_core is signal req,oh:std_logic_vector(7 downto 0);signal v:std_logic;signal idx:std_logic_vector(2 downto 0);begin dut:entity work.bbq_priority_encoder_core generic map(INPUTS=>8,HIGH_PRIORITY=>true)port map(req,v,idx,oh);process begin req<="00101000";wait for 1 ns;assert v='1' and idx="101" and oh="00100000" severity failure;req<=(others=>'0');wait for 1 ns;assert v='0' severity failure;report "PASS" severity note;stop;wait;end process;end;
